# 20_identifiability_A.R: mathematical identifiability of the explicit spread-by-position interaction (current package parameterisation, spread = "varying"; plus the focal-only restriction).
# For k = 2, 3, 4, 5, 8 on (i) random, (ii) balanced and (iii) EPA (BM, shared pool, log10 TP/TN/Chl-a) combinations: rank, singular values and scaled condition number of the full design, rank of the additive design,
# the interaction increment (U-endpoint columns u * base spread; the L columns equal base - U) projected onto the orthogonal complement of the additive design, the independent information remaining, exact/approximate linear
# dependencies (null and near-null singular vectors), the k = 2 algebraic identity, and the package's own ugdm_interaction_diagnostics() on a fitted model. Run from final/ with ZG_LIB6 set.
source("revision_ident/00_ident_common.R"); source("revision_ident/01_balanced_design.R"); ORDERS <- c(2, 3, 4, 5, 8); REF <- ref_design()
tol_rank <- function(sv, m, n) max(sv) * max(m, n) * .Machine$double.eps
src_sets <- function(src, k) { if (src == "random2") { cfg <- random_configs(k, 1680, 11 + k); list(env = cfg$env, idx = cfg$idx, ref = REF) } else if (src == "balanced2") { cfg <- balanced_configs(k, 40, 21 + k); list(env = cfg$env, idx = cfg$idx, ref = REF) }
  else { P <- readRDS("out/pools.rds"); d <- P$shared$BM; e <- data.frame(TP = log10(d$env$TP), TN = log10(d$env$TN), Chla = log10(d$env$Chla)); list(env = e, idx = sample_sets(nrow(e), k, 3000, seed = 31 + k), ref = NULL) } }
rows <- list(); resid_rows <- list(); null_rows <- list(); k2_rows <- list(); diag_rows <- list()
for (src in c("random2", "balanced2", "epa")) for (k in ORDERS) { S <- src_sets(src, k); vars <- names(S$env); focal <- vars[1]
  for (lay in c("package_all_predictors", "focal_only")) { spec_i <- list(type = "interaction", focal = if (lay == "focal_only") focal else NULL); bi <- build_X(S$env, S$idx, spec_i, S$ref); ba <- build_X(S$env, S$idx, list(type = "additive"), S$ref); Xi <- bi$X; Xa <- ba$X
    sc <- function(M) sweep(M, 2, sqrt(colSums(M^2)), "/"); svi <- svd(sc(Xi), nu = 0, nv = ncol(Xi))$d; sva <- svd(sc(Xa), nu = 0)$d; ri <- sum(svi > tol_rank(svi, nrow(Xi), ncol(Xi))); ra <- sum(sva > tol_rank(sva, nrow(Xa), ncol(Xa)))
    Ucols <- grep("_f[123]_U$", colnames(Xi)); Xinc <- Xi[, Ucols, drop = FALSE]; Xc <- sweep(Xinc, 2, colMeans(Xinc)); Rr <- qr.resid(qr(Xa), Xinc); tot <- colSums(Xc^2); frac <- colSums(Rr^2) / tot; sr <- svd(Rr, nu = 0, nv = 0)$d; sx <- svd(Xc, nu = 0, nv = 0)$d
    rows[[length(rows) + 1]] <- data.frame(source = src, layout = lay, order = k, n_sets = nrow(Xi), n_parameters_full = ncol(Xi), rank_full = ri, rank_additive = ra, n_parameters_additive = ncol(Xa), sv_max = max(svi), sv_min = min(svi), scaled_condition = max(svi) / min(svi), scaled_condition_additive = max(sva) / min(sva), n_interaction_columns = length(Ucols),
      interaction_info_fraction_mean = mean(frac), interaction_info_fraction_min = min(frac), interaction_info_fraction_max = max(frac), interaction_info_fraction_pooled = sum(colSums(Rr^2)) / sum(tot), effective_dims_residual_1pct = sum(sr / max(sr) > .01), effective_dims_residual_10pct = sum(sr / max(sr) > .10), sv_residual_max = max(sr), sv_increment_max = max(sx), rank_increment_residual = sum(sr > tol_rank(sr, nrow(Rr), ncol(Rr))))
    resid_rows[[length(resid_rows) + 1]] <- data.frame(source = src, layout = lay, order = k, column = colnames(Xinc), residual_fraction = frac)
    # exact / approximate dependencies: right singular vectors of the column-scaled full design
    sv <- svd(sc(Xi), nu = 0, nv = ncol(Xi)); for (r in which(sv$d / max(sv$d) < 1e-3)) { lo <- sv$v[, r]; ord <- order(-abs(lo))[1:4]; null_rows[[length(null_rows) + 1]] <- data.frame(source = src, layout = lay, order = k, singular_value_ratio = sv$d[r] / max(sv$d), kind = ifelse(sv$d[r] / max(sv$d) < 1e-10, "exact", "approximate"), top_loadings = paste(sprintf("%s:%.2f", colnames(Xi)[ord], lo[ord]), collapse = " ")) }
    if (lay == "package_all_predictors" && src != "epa") { y <- plogis(-1 + 1.2 * ba$X[, 2] + .6 * ba$X[, 5] + .15 * ba$X[, which(colnames(ba$X) == "P")]); set.seed(5); yn <- rbinom(length(y), 60, y) / 60; pk <- ugdm_interaction_design(ba$d0, S$env, position = "nonlinear", spread = "varying"); ft <- ugdm_fit_interactions(pk, yn, rep(60, length(yn)), distance = FALSE, spread_smooth = .002, position_smooth = .002, interaction_shrink = 1e-6, ridge = 1e-4)
      dg <- ugdm_interaction_diagnostics(ft, pk, yn, rep(60, length(yn))); diag_rows[[length(diag_rows) + 1]] <- data.frame(source = src, order = k, package_rank = dg$rank, package_parameters = dg$parameters, package_condition = dg$condition, package_active_constraints = length(dg$active), package_interaction_residual_min = min(dg$interaction_residual), package_interaction_residual_median = median(dg$interaction_residual), package_interaction_residual_max = max(dg$interaction_residual), package_interaction_deviance_allocation = dg$deviance_allocation[["interaction"]], package_additive_D2 = dg$additive_D2, package_full_D2 = dg$full_D2) } }
  # k = 2 algebraic identity (focal predictor, standardised values): u * |a - b| = |a^2 - b^2| / 2 when a and b share a sign; compare with additive span
  if (src != "epa") { Z <- scale(S$env[[focal]], center = ref_design()$d0$environment_basis$center[[focal]], scale = ref_design()$d0$environment_basis$scale[[focal]]); A <- Z[S$idx[, 1]]; B <- Z[S$idx[, min(2, ncol(S$idx))]]; mm <- (A + B) / 2; lin <- abs(A - B) * mm; sq <- abs(A^2 - B^2) / 2; same <- sign(A) == sign(B); ba <- build_X(S$env, S$idx, list(type = "additive"), S$ref); r2 <- function(v) 1 - sum(qr.resid(qr(ba$X), v)^2) / sum((v - mean(v))^2)
    k2_rows[[length(k2_rows) + 1]] <- data.frame(source = src, order = k, note = if (k == 2) "pairs" else "first two sites of each set (illustration only)", prop_same_sign = mean(same), max_abs_identity_error_same_sign = if (any(same)) max(abs(lin[same] - sq[same])) else NA, R2_linear_spread_x_position_on_additive_design = r2(lin), R2_abs_diff_squares_on_additive_design = r2(sq),
      R2_U_endpoint_columns_on_additive_design = mean(1 - resid_rows[[length(resid_rows)]]$residual_fraction)) } }
O <- OUT <- "revision_ident/tables"; write.csv(bind_rows(rows), file.path(OUT, "identifiability_A_rank_summary.csv"), row.names = FALSE); write.csv(bind_rows(resid_rows), file.path(OUT, "identifiability_A_residual_by_column.csv"), row.names = FALSE); write.csv(bind_rows(null_rows), file.path(OUT, "identifiability_A_dependencies.csv"), row.names = FALSE); write.csv(bind_rows(k2_rows), file.path(OUT, "identifiability_A_k2_identity.csv"), row.names = FALSE); write.csv(bind_rows(diag_rows), file.path(OUT, "identifiability_A_package_diagnostics.csv"), row.names = FALSE)
options(width = 220, digits = 3); print(as.data.frame(bind_rows(rows) |> filter(layout == "package_all_predictors") |> select(source, order, n_parameters_full, rank_full, rank_additive, scaled_condition, interaction_info_fraction_mean, interaction_info_fraction_min, effective_dims_residual_10pct)))
